"""Standalone GUI for fixed-geometry particle packing using five embedded scripts.

Original source texts are embedded verbatim. Only user-input assignments are
overridden in memory; computational functions and original annotations are kept.
"""
import ast
import base64
import hashlib
import json
import os
from pathlib import Path
import queue
import shutil
import subprocess
import sys
import threading
import types
from datetime import datetime

SOURCE_BUNDLE = {'distribution.py': '', 'distributiton-main.py': '', 'collision.py': '', 'main.py': '', 'Model simulation.py': ''}


def source(name):
    return base64.b64decode(SOURCE_BUNDLE[name]).decode('utf-8-sig')


def execute(name, namespace, overrides=None):
    """Change only top-level input assignments, never algorithm bodies."""
    tree = ast.parse(source(name), filename=name)
    overrides = overrides or {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id in overrides:
                    value = overrides[target.id]
                    node.value = ast.parse(repr(value), mode='eval').body
    exec(compile(ast.fix_missing_locations(tree), name, 'exec'), namespace)


def load_module(name, filename, overrides=None):
    module = types.ModuleType(name)
    module.__file__ = filename
    sys.modules[name] = module
    execute(filename, module.__dict__, overrides)
    return module


def worker(request_file):
    request = json.loads(Path(request_file).read_text(encoding='utf-8'))
    directory = Path(request['directory'])
    os.chdir(directory)
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    stage = request['stage']
    try:
        if stage == 'distribution':
            original = ast.parse(source('distribution.py'))
            params = next(ast.literal_eval(n.value) for n in original.body if isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'PARAMS' for t in n.targets))
            params['particle_mass'] = dict(zip('abcd', request['masses']))
            execute('distribution.py', {'__name__': '__main__', '__file__': 'distribution.py'}, {'PARAMS': params})
            required = ['geometry_quantity.csv']
        elif stage == 'batch':
            load_module('distribution', 'distribution.py')
            execute('distributiton-main.py', {'__name__': '__main__', '__file__': 'distributiton-main.py'}, {'num_distribution': request['total_mass']})
            required = [f'distribution-all/{i:02d}/geometry_quantity.csv' for i in range(1, 36)]
        elif stage == 'collision':
            execute('collision.py', {'__name__': '__main__', '__file__': 'collision.py'})
            required = ['polyhedron_data/5.valid_chains.csv']
        elif stage == 'simulation':
            import importlib.util
            dependencies = {'pyvista': 'pyvista', 'cadquery': 'cadquery', 'OCC': 'pythonocc-core'}
            missing_dependencies = [package for module, package in dependencies.items()
                                    if importlib.util.find_spec(module) is None]
            if missing_dependencies:
                raise RuntimeError('STEP export requires additional packages in this Python environment: '
                                   + ', '.join(missing_dependencies))
            execute('Model simulation.py', {'__name__': '__main__', '__file__': 'Model simulation.py'})
            required = ['polyhedron_data/' + name for name in
                        ['1.polyhedrons.png', '2.polyhedrons.step', '3.space.step', '4.remaining_space.step']]
        elif stage == 'repeat':
            package = types.ModuleType('core')
            package.__path__ = []
            sys.modules['core'] = package
            package.collision = load_module('core.collision', 'collision.py')
            execute('main.py', {'__name__': '__main__', '__file__': 'main.py'}, {'num_iterations': request['repeats']})
            required = ['iteration-all/main.csv'] + [f'iteration-all/iteration{i}/5.valid_chains.csv' for i in range(1, request['repeats'] + 1)]
        else:
            raise ValueError(f'Unknown stage: {stage}')
        missing = [name for name in required if not (directory / name).is_file()]
        if missing:
            raise RuntimeError(f'Original script did not produce required outputs: {missing}')
        (directory / 'gui_status.json').write_text(json.dumps({'status': 'complete', 'stage': stage}, indent=2), encoding='utf-8')
    except BaseException as error:
        (directory / 'gui_status.json').write_text(json.dumps({'status': 'failed', 'stage': stage, 'error': str(error)}, indent=2), encoding='utf-8')
        raise
    finally:
        plt.close('all')


def gui():
    import tkinter as tk
    from tkinter import ttk, filedialog, messagebox
    import math

    class App:
        def __init__(self, root):
            self.root = root
            root.title('Particle random distribution and geometry export')
            root.geometry('980x870')
            self.events = queue.Queue()
            self.process = None
            self.busy = False
            self.geometry_dir = None
            self.quantity_file = None
            self.batch_dir = None
            self.latest_dir = None
            self.selection = None
            self.counter = 0
            self.run_root = None
            self.output_directory = Path(__file__).resolve().parent / 'GUI_runs'
            self.out = tk.StringVar()
            self.geometry_display = tk.StringVar()
            self.status = tk.StringVar(value='Select the two geometry CSV files to begin.')
            self.active = tk.StringVar(value='Current formulation: not selected')
            self.controls = []
            frame = ttk.Frame(root, padding=12)
            frame.pack(fill='both', expand=True)
            ttk.Label(frame, text='Select inputs and run each step in order.').pack(anchor='w')
            output = ttk.Frame(frame)
            output.pack(fill='x', pady=7)
            ttk.Label(output, text='Output folder:').pack(side='left')
            ttk.Entry(output, textvariable=self.out, state='readonly').pack(side='left', fill='x', expand=True)
            self.button(output, 'Browse', self.choose_output).pack(side='left', padx=5)

            one = self.section(frame, '1  Particle geometry - Load fixed geometry CSV files')
            self.button(one, 'Select geometry CSV files', self.import_geometry).pack(side='left', padx=5)
            ttk.Entry(one, textvariable=self.geometry_display, state='readonly', width=58).pack(side='left', padx=5)

            two = self.section(frame, '2  Custom formulation')
            self.masses = []
            for category, initial in zip('abcd', ['1', '0', '0', '1']):
                ttk.Label(two, text=f'{category} mass (g)').pack(side='left')
                value = tk.StringVar(value=initial)
                self.masses.append(value)
                ttk.Entry(two, textvariable=value, width=7).pack(side='left', padx=4)
            self.button(two, 'Calculate particle counts', self.custom).pack(side='left', padx=8)

            three = self.section(frame, '3  Batch formulations (optional alternative to step 2)')
            ttk.Label(three, text='Total PLA mass (g)').pack(side='left')
            self.total = tk.StringVar(value='12')
            ttk.Entry(three, textvariable=self.total, width=7).pack(side='left', padx=4)
            self.button(three, 'Generate 35 formulations', self.batch).pack(side='left', padx=4)
            self.group = tk.StringVar(value='01')
            ttk.Combobox(three, textvariable=self.group, values=[f'{i:02d}' for i in range(1,36)], state='readonly', width=5).pack(side='left', padx=4)
            self.button(three, 'Use selected group', self.select_group).pack(side='left', padx=4)

            ttk.Label(frame, textvariable=self.active, wraplength=930, foreground='#174c72').pack(anchor='w', pady=8)
            four = self.section(frame, '4  Single random packing')
            self.button(four, 'Run selected formulation', lambda: self.start('collision')).pack(side='left', padx=5)
            ttk.Label(four, text='Save packing images and contact-chain results.').pack(side='left')
            five = self.section(frame, '5  Repeated packing')
            ttk.Label(five, text='Repetitions').pack(side='left')
            self.repeats = tk.StringVar(value='3')
            ttk.Entry(five, textvariable=self.repeats, width=8).pack(side='left', padx=4)
            self.button(five, 'Run repetitions', self.repeat).pack(side='left', padx=5)
            ttk.Label(five, text='Repeat packing and summarize counts in main.csv.').pack(side='left')
            six = self.section(frame, '6  Simulation geometry and STEP export')
            self.button(six, 'Generate STEP files', lambda: self.start('simulation')).pack(side='left', padx=5)
            ttk.Label(six, text='Generate a new packing with the selected formulation.').pack(side='left')
            row = ttk.Frame(frame)
            row.pack(fill='x', pady=6)
            ttk.Button(row, text='Open latest results', command=self.open_output).pack(side='left')
            ttk.Button(row, text='Stop current operation', command=self.stop).pack(side='left', padx=8)
            ttk.Label(frame, textvariable=self.status, wraplength=930).pack(anchor='w', pady=5)
            logs = ttk.Frame(frame)
            logs.pack(fill='both', expand=True)
            self.log = tk.Text(logs, height=13, wrap='word')
            self.log.pack(side='left', fill='both', expand=True)
            scroll = ttk.Scrollbar(logs, command=self.log.yview)
            scroll.pack(side='right', fill='y')
            self.log.configure(yscrollcommand=scroll.set)
            root.after(100, self.poll)
            root.protocol('WM_DELETE_WINDOW', self.close)

        def button(self, parent, text, action):
            widget = ttk.Button(parent, text=text, command=action)
            self.controls.append(widget)
            return widget

        def section(self, parent, title):
            box = ttk.LabelFrame(parent, text=title, padding=8)
            box.pack(fill='x', pady=5)
            return box

        def choose_output(self):
            directory = filedialog.askdirectory()
            if directory:
                self.output_directory = Path(directory)
                self.out.set('Selected')
                self.run_root = None

        def new_directory(self, stage):
            if self.run_root is None:
                self.run_root = self.output_directory.expanduser().resolve() / datetime.now().strftime('%Y%m%d_%H%M%S_%f')
            self.counter += 1
            directory = self.run_root / f'{self.counter:02d}_{stage}'
            directory.mkdir(parents=True, exist_ok=False)
            return directory

        def reset_geometry(self, directory):
            self.geometry_dir = directory
            self.quantity_file = None
            self.batch_dir = None
            self.selection = None
            self.active.set('Current formulation: select a formulation in step 2 or 3.')

        def import_geometry(self):
            chosen = filedialog.askopenfilenames(title='Select geometry_cutpoints.csv and geometry_volumes.csv', filetypes=[('CSV files', '*.csv')])
            if not chosen:
                return
            try:
                files = [Path(name) for name in chosen]
                if len(files) != 2 or {path.name for path in files} != {'geometry_cutpoints.csv', 'geometry_volumes.csv'} or not all(path.is_file() for path in files):
                    raise ValueError('Select both geometry_cutpoints.csv and geometry_volumes.csv.')
                directory = self.new_directory('geometry_import')
                for path in files:
                    shutil.copy2(path, directory / path.name)
                self.reset_geometry(directory)
                self.latest_dir = directory
                self.geometry_display.set('geometry_cutpoints.csv; geometry_volumes.csv')
                self.status.set('Geometry files loaded successfully.')
            except Exception as error:
                messagebox.showerror('Unable to load files', str(error))

        def custom(self):
            try:
                masses = [float(value.get()) for value in self.masses]
                if not all(math.isfinite(x) and x >= 0 for x in masses) or sum(masses) <= 0:
                    raise ValueError('Masses must be finite and nonnegative, with a positive total.')
                self.start('distribution', masses=masses)
            except ValueError as error:
                messagebox.showerror('Invalid input', str(error))

        def batch(self):
            try:
                mass = float(self.total.get())
                if not math.isfinite(mass) or mass <= 0:
                    raise ValueError('Total mass must be finite and positive.')
                self.start('batch', total_mass=mass)
            except ValueError as error:
                messagebox.showerror('Invalid input', str(error))

        def repeat(self):
            try:
                repeats = int(self.repeats.get())
                if repeats <= 0:
                    raise ValueError('Repetitions must be a positive integer.')
                self.start('repeat', repeats=repeats)
            except ValueError as error:
                messagebox.showerror('Invalid input', str(error))

        def quantity_preview(self, path):
            import pandas as pd
            data = pd.read_csv(path)
            return '; '.join(f'{row[0]}: {row[1]:g} -> {max(0, round(row[1]))} particles' for row in data.itertuples(index=False, name=None))

        def select_group(self):
            if self.batch_dir is None:
                messagebox.showinfo('Generate formulations first', 'Click Generate 35 formulations first.')
                return
            path = self.batch_dir / 'distribution-all' / self.group.get() / 'geometry_quantity.csv'
            preview = self.quantity_preview(path)
            if messagebox.askokcancel('Confirm formulation', f'Use group {self.group.get()}?\n{preview}'):
                self.quantity_file = path
                request = json.loads((self.batch_dir / 'gui_request.json').read_text(encoding='utf-8'))
                self.selection = {'mode': 'batch', 'total_mass': request['total_mass'], 'group': self.group.get()}
                self.active.set(f'Current formulation: {request["total_mass"]:g} g, group {self.group.get()}; {preview}')

        def start(self, stage, **parameters):
            if self.busy:
                return
            if self.geometry_dir is None:
                messagebox.showinfo('Missing geometry', 'Complete step 1 first.')
                return
            if stage in ['collision', 'repeat', 'simulation'] and self.quantity_file is None:
                messagebox.showinfo('Missing formulation', 'Select a formulation in step 2 or 3 first.')
                return
            try:
                directory = self.new_directory(stage)
                for name in ['geometry_cutpoints.csv', 'geometry_volumes.csv']:
                    shutil.copy2(self.geometry_dir / name, directory / name)
                if stage in ['collision', 'repeat', 'simulation']:
                    shutil.copy2(self.quantity_file, directory / 'geometry_quantity.csv')
                request = {'stage': stage, 'directory': str(directory), **parameters, 'selection': self.selection,
                           'source_hashes': {name: hashlib.sha256(base64.b64decode(value)).hexdigest() for name,value in SOURCE_BUNDLE.items()}}
                request_file = directory / 'gui_request.json'
                request_file.write_text(json.dumps(request, ensure_ascii=False, indent=2), encoding='utf-8')
                executable = Path(sys.executable)
                if executable.name.lower() == 'pythonw.exe':
                    executable = executable.with_name('python.exe')
                self.process = subprocess.Popen([str(executable), '-u', '-X', 'utf8', str(Path(__file__).resolve()), '--worker', str(request_file)], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, encoding='utf-8', errors='replace', creationflags=subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0)
                self.busy = True
                self.latest_dir = directory
                for widget in self.controls:
                    widget.configure(state='disabled')
                self.status.set(f'Running {stage}. See the progress log below.')
                process = self.process
                def collect():
                    with (directory / 'gui_run.log').open('w', encoding='utf-8') as log:
                        for line in process.stdout:
                            log.write(line)
                            self.events.put(('log', line))
                    code = process.wait()
                    self.events.put(('done', (code, request, directory)))
                threading.Thread(target=collect, daemon=True).start()
            except Exception as error:
                messagebox.showerror('Unable to start', str(error))

        def poll(self):
            for _ in range(250):
                try:
                    kind, payload = self.events.get_nowait()
                except queue.Empty:
                    break
                if kind == 'log':
                    display = payload
                    if any('\u3400' <= char <= '\u9fff' for char in display):
                        display = 'Processing... Details recorded in gui_run.log.\n'
                    elif ':\\' in display or ':/' in display:
                        display = 'File operation recorded in gui_run.log.\n'
                    self.log.insert('end', display)
                    self.log.see('end')
                else:
                    code, request, directory = payload
                    self.busy = False
                    for widget in self.controls:
                        widget.configure(state='normal')
                    if code == 0:
                        stage = request['stage']
                        if stage == 'distribution':
                            self.quantity_file = directory / 'geometry_quantity.csv'
                            self.selection = {'mode': 'custom', 'masses': request['masses']}
                            self.active.set(f'Current formulation: masses {request["masses"]} g; {self.quantity_preview(self.quantity_file)}')
                        elif stage == 'batch':
                            self.batch_dir = directory
                        self.status.set(f'Completed: {stage}.' + (' Select and confirm a group.' if stage == 'batch' else ''))
                    else:
                        self.status.set(f'Operation did not complete (exit code {code}). Open latest results to inspect the log.')
            self.root.after(100, self.poll)

        def open_output(self):
            if self.latest_dir:
                os.startfile(str(self.latest_dir))

        def stop(self):
            if self.busy and self.process and messagebox.askyesno('Stop operation', 'Stop this step? Existing output files will be retained.'):
                self.process.terminate()

        def close(self):
            if self.busy:
                if not messagebox.askyesno('Close', 'Stop the running operation and close this window?'):
                    return
                self.process.terminate()
            self.root.destroy()

    root = tk.Tk()
    App(root)
    root.mainloop()


if __name__ == '__main__':
    if len(sys.argv) == 3 and sys.argv[1] == '--worker':
        worker(sys.argv[2])
    else:
        gui()
